class ParallelCollector {
    fun bad(list: List<String>) {
        val inUpperCase = ArrayList<String>()
        list.parallelStream().forEach { inUpperCase.add(it.uppercase()) }
    }
}

class ParallelCollector {
    fun bad(list: List<String>) {
        val results = mutableListOf<String>()
        list.stream().parallel().forEach { results.add(it) }
    }
}

class ParallelCollector {
    fun good(list: List<String>): List<String> {
        return list.parallelStream().map { it.uppercase() }.toList()
    }
}

class ParallelCollector {
    fun good(list: List<String>) {
        list.parallelStream().forEach { println(it) }
    }
}
